{
  "name": "scan_done_check",
  "confidence": "medium",
  "docstring": "Checks a pending scan-complete condition and, when the relevant status flag is set, forwards the associated LL RX PDU to llm_rx_pdu_handler and stores the derived status; otherwise it clears the related IRQ if the scanned signed state value is negative.",
  "subsystem": "bt",
  "var_renames": {
    "v2": "rx_pdu_ctx",
    "v3": "llm_rx_status"
  },
  "struct_hints": [
    {
      "offset": 76,
      "meaning": "pointer to an LL RX descriptor/context from the scan context (a2)"
    },
    {
      "offset": 48,
      "meaning": "pointer to the RX PDU context within the LL RX descriptor"
    },
    {
      "offset": 36,
      "meaning": "RX status field updated from the handler return value"
    },
    {
      "offset": 20,
      "meaning": "packed RX PDU information word: low 7 bits and bits 11-13 are extracted as handler arguments"
    },
    {
      "offset": 72,
      "meaning": "pointer to an RX payload/base buffer within the source context (first argument)"
    }
  ]
}
